  {"id":"e83","type":"Conference","title":"2027 International Conference on Electrical, Computer and Communication Engineering (ECCE 2027)","start":"","end":"","dateText":"January or February 2027 (the organiser’s pages differ: 21–23 January or 4–6 February 2027)","city":"Chattogram","country":"Bangladesh","region":"Asia-Pacific","format":"In person","organiser":"Faculty of Electrical and Computer Engineering, Chittagong University of Engineering & Technology (CUET)","theme":"ai","sector":"Telecom","cost":"Not stated (see the conference registration page)","note":"Venue: CUET campus, Chattogram. Academic conference; accepted papers to be submitted to IEEE Xplore. Tracks include cyber security and cryptography; AI, machine learning, blockchain and IoT; big data and cloud; and e-commerce, e-governance and IT strategy. Paper submission closed (extended to 15 November 2026); acceptance notices due 15 December 2026. Dates to be confirmed: the website header shows 4–6 February 2027, while the call for papers says 21–23 January 2027.","url":"https://ecce2027.cuet.ac.bd","source":["ECCE 2027","CUET, official conference site","https://ecce2027.cuet.ac.bd"],"checked":"2026-11-25"},
  {"id": "e84", "type": "Workshop", "title": "DPDP Act Readiness Workshop in Lucknow", "start": "2026-12-02", "end": "2026-12-02", "dateText": "2 December 2026", "city": "Lucknow", "country": "India", "region": "Asia-Pacific", "format": "In person", "organiser": "National e-Governance Division (NeGD), Ministry of Electronics and Information Technology, Government of India", "theme": "pol", "sector": "Government", "cost": "Not stated", "note": "Part of NeGD's series of regional workshops on readiness for India's Digital Personal Data Protection (DPDP) Act. Later stops: Guwahati (8 Dec), Indore (15 Dec), Chennai (18 Dec) and Bhubaneswar (21 Dec 2026).", "url": "https://negd.gov.in/events/", "source": ["Events: DPDP Act Readiness Workshop, Lucknow (02-12-2026)", "National e-Governance Division, events page (last updated 23 Nov 2026)", "https://negd.gov.in/events/"], "checked": "2026-11-25"},
  {"id": "e85", "type": "Training", "title": "GIG-ARTS School on Digital Governance", "start": "2027-02-22", "end": "2027-02-26", "dateText": "22 to 26 February 2027, 09:00–17:00", "city": "Bruges", "country": "Belgium", "region": "Europe", "format": "In person", "organiser": "United Nations University Institute on Comparative Regional Integration Studies (UNU-CRIS), with support from the City of Bruges and the Province of West Flanders", "theme": "pol", "sector": "Government", "cost": "Not stated", "note": "Applications close 31 December 2026; places are limited. For graduate students, early-career researchers, ICT professionals and policymakers; covers governance of standards, telecoms, platforms, AI and data, digital sovereignty and cybersecurity. The page does not name a venue or state whether online attendance is possible.", "url": "https://unu.edu/cris/event/gig-arts-school-digital-governance", "source": ["GIG-ARTS School on Digital Governance", "UNU-CRIS, event page", "https://unu.edu/cris/event/gig-arts-school-digital-governance"], "checked": "2026-11-25"},
  {"id": "e86", "type": "Webinar", "title": "Sovereign digital infrastructure in Canada: what it means and how to do it", "start": "2027-02-25", "end": "2027-02-25", "dateText": "February 25, 2027, 10:30–11:45 EST", "city": "Online", "country": "Online", "region": "Online", "format": "Online", "organiser": "Global Government Forum", "theme": "egov", "sector": "Government", "cost": "Free for public servants", "note": "", "url": "https://www.globalgovernmentforum.com/events/sovereign-digital-infrastructure-in-canada-what-it-means-and-how-to-do-it/", "source": ["Sovereign digital infrastructure in Canada: what it means and how to do it", "Global Government Forum, event page", "https://www.globalgovernmentforum.com/events/sovereign-digital-infrastructure-in-canada-what-it-means-and-how-to-do-it/"], "checked": "2026-11-25"},
  {id:'e87', type:'Webinar', title:'Korea’s Digital Government Model: An Evidence-Based Case Study (CADGov Forum webinar 3)', start:'2026-12-09', end:'2026-12-09', dateText:'9 December 2026, 11:00–12:30 Lisbon time (16:00–17:30 Tashkent)', city:'Online', country:'Online', region:'Online', format:'Online', organiser:'United Nations University Operating Unit on Policy-Driven Electronic Governance (UNU-EGOV)', theme:'egov', sector:'Government', cost:'Not stated (registration required)', note:'Third webinar in the CADGov Forum series, part of UNU-EGOV’s capacity-building diploma for Central Asian public officials on digital governance and AI readiness. Speakers from Korea’s National Information Society Agency (NIA) and Kookmin University look at how Korea moved from early e-government to AI-enabled services, and what other countries can and cannot borrow from it. Register through the form on the event page; the access link is sent after registration.', url:'https://unu.edu/egov/seminar/koreas-digital-government-model-evidence-based-case-study', source:['Korea’s Digital Government Model: An Evidence-Based Case Study','UNU-EGOV, event page (accessed 26 Nov 2026)','https://unu.edu/egov/seminar/koreas-digital-government-model-evidence-based-case-study'], checked:'2026-11-26'},
  {id:'e88', type:'Seminar', title:'PIX in Brazil: From Mass Adoption to Unintended Consequences', start:'2026-12-09', end:'2026-12-09', dateText:'9 December 2026, 14:00–15:00 Lisbon time', city:'Online', country:'Online', region:'Online', format:'Online', organiser:'United Nations University Operating Unit on Policy-Driven Electronic Governance (UNU-EGOV)', theme:'dpi', sector:'Fintech & payments', cost:'Not stated (registration required)', note:'Seminar by Luiz A. Joia (FGV EBAPE) on why Brazil’s central-bank instant payment system Pix spread so fast, and on its side effects, including fraud, criminal use and financial vulnerability. Aimed at policymakers and researchers working on payment infrastructure and financial inclusion. UNU-EGOV names no venue and sends an access link after registration, so the session appears to be online.', url:'https://unu.edu/egov/seminar/pix-brazil-mass-adoption-unintended-consequences', source:['PIX in Brazil: From Mass Adoption to Unintended Consequences','UNU-EGOV, event page (accessed 26 Nov 2026)','https://unu.edu/egov/seminar/pix-brazil-mass-adoption-unintended-consequences'], checked:'2026-11-26'},
  {id:'e89', type:'Forum', title:'Nasscom Technology & Leadership Forum 2027 (NTLF, 35th edition)', start:'2027-02-24', end:'2027-02-25', dateText:'24–25 February 2027', city:'Mumbai', country:'India', region:'Asia-Pacific', format:'In person', organiser:'Nasscom (National Association of Software and Service Companies)', theme:'ai', sector:'Trade & business', cost:'Not stated', note:'India’s main annual gathering of the IT and technology services industry, with policymakers, company leaders and start-ups. The 2027 programme is built around four pillars, three of them on AI: the intelligence dividend, enterprise AI, the human side of AI, and science and deep tech. Venue reported as The Fairmont, Mumbai; dates are taken from a trade report citing Nasscom’s event page, so check with Nasscom before booking.', url:'https://nasscom.in/ntlf', source:['Nasscom NTLF 2027 (24 to 25 Feb): what IT leaders will debate on AI services','eCorpIT, 1 Nov 2026','https://ecorpit.com/nasscom-ntlf-2027-india-it-ai-services/'], checked:'2026-11-26'}
